# Keep the whole OHOS namespace surface (OHOS::NetStack::* utilities and the
# netmanager_base NDK inline singleton NetConnClient::instance_/instanceMtx_
# defined here and referenced cross-DSO). Hide std::__h inline instantiations
# and other non-contract leaks. Mangled wildcard is feature-switch proof
# (HAS_NETMANAGER_BASE=0/1 both compile into OHOS namespaces).

{
  global:
    _Z*4OHOS*;
  local:
    *;
};
